#include "helpers/SkeletonHelper.h"
namespace{thread_local Vector3 vector;thread_local Matrix4 boneMatrix,matrixWorldInv;
std::vector<std::shared_ptr<Object3D>> getBoneList(const std::shared_ptr<Object3D>& object){if(!object)throw JSTypeError("Cannot read properties of undefined (reading 'isBone')");std::vector<std::shared_ptr<Object3D>> result;if(object->isBone)result.push_back(object);for(std::size_t i=0;i<object->children.size();++i){const auto next=getBoneList(object->children[i]);result.insert(result.end(),next.begin(),next.end());}return result;}
std::shared_ptr<BufferGeometry> createGeometry(const std::vector<std::shared_ptr<Object3D>>& bones){std::vector<double> vertices,colors;for(const auto& bone:bones)if(bone->parent&&bone->parent->isBone){vertices.insert(vertices.end(),{0,0,0,0,0,0});colors.insert(colors.end(),{0,0,0,0,0,0});}auto result=Helper_detail::geometry(vertices);result->setAttribute("color",std::make_shared<Float32BufferAttribute>(colors,3));return result;}
std::shared_ptr<LineBasicMaterial> createMaterial(){auto result=Helper_detail::lineMaterial({},true);result->depthTest=false;result->depthWrite=false;result->transparent=true;return result;}}
SkeletonHelper::SkeletonHelper(std::shared_ptr<Object3D> object):SkeletonHelper(object,getBoneList(object)){}
SkeletonHelper::SkeletonHelper(std::shared_ptr<Object3D> object,std::vector<std::shared_ptr<Object3D>> values):LineSegments(createGeometry(values),createMaterial()),root(std::move(object)),bones(std::move(values)){isSkeletonHelper=true;type="SkeletonHelper";matrix.aliasTo(std::shared_ptr<Matrix4>(root,&root->matrixWorld),root);matrixAutoUpdate=false;setColors(Color(0x0000ff),Color(0x00ff00));}
void SkeletonHelper::updateMatrixWorld(bool force){const auto bones=this->bones;const auto geometry=this->geometry;const auto position=geometry->getAttribute("position");if(!root)throw JSTypeError("root is undefined");matrixWorldInv.copy(root->matrixWorld).invert();for(std::size_t i=0,j=0;i<bones.size();++i){const auto bone=bones[i];if(!bone)throw JSTypeError("bone is undefined");if(bone->parent&&bone->parent->isBone){boneMatrix.multiplyMatrices(matrixWorldInv,bone->matrixWorld);vector.setFromMatrixPosition(boneMatrix);position->setXYZ(double(j),vector.x,vector.y,vector.z);boneMatrix.multiplyMatrices(matrixWorldInv,bone->parent->matrixWorld);vector.setFromMatrixPosition(boneMatrix);position->setXYZ(double(j+1),vector.x,vector.y,vector.z);j+=2;}}geometry->getAttribute("position")->setNeedsUpdate(true);LineSegments::updateMatrixWorld(force);}
SkeletonHelper& SkeletonHelper::setColors(const Color& color1,const Color& color2){const auto attribute=geometry->getAttribute("color");if(!attribute)throw JSTypeError("color attribute is undefined");for(double i=0;i<attribute->getCount();i+=2){attribute->setXYZ(i,color1.r,color1.g,color1.b);attribute->setXYZ(i+1,color2.r,color2.g,color2.b);}attribute->setNeedsUpdate(true);return *this;}
std::shared_ptr<Object3D> SkeletonHelper::clone(bool)const{return std::make_shared<SkeletonHelper>(nullptr);}
void SkeletonHelper::dispose(){LineSegments::dispose();Helper_detail::disposeGeometry(geometry);Helper_detail::disposeMaterial(material);}
